{"command":"python3 - <<'EOF'
import csv
with open('outputs/t02_eurostat_raw.csv', newline='', encoding='utf-8') as f:
    rows = list(csv.DictReader(f))
indicators = []
for r in rows:
    if r['indicator_id'] not in indicators:
        indicators.append(r['indicator_id'])
data = {}
names = {}
for r in rows:
    key = (r['city_id'], r['year'])
    data[key] = data.get(key, {})
    data[key][r['indicator_id']] = r['value']
    names[r['city_id']] = r['city_name']
with open('outputs/t11_city_indicator_matrix.csv', 'w', newline='', encoding='utf-8') as f:
    w = csv.writer(f, quoting=csv.QUOTE_MINIMAL, lineterminator='\r\n')
    w.writerow(['city_id','city_name','year'] + indicators)
    for city_id, year in sorted(data.keys()):
        vals = data[(city_id, year)]
        w.writerow([city_id, names[city_id], year] + [vals.get(ind, '') for ind in indicators])
print("done")
EOF"}
